// Exact four-bridge zero-crossing test for core4. No arbitrary-crossing claim.
#include <bits/stdc++.h>
using namespace std;using E=vector<pair<int,int>>;struct Pat{int u,v;vector<E>a,b;};vector<Pat>fam;vector<E>twoB;E cur,fa,fb;vector<array<uint64_t,2>> BS;map<array<uint64_t,2>,vector<E>> bm;ofstream residual;long long residualcount=0;array<int,16> par;long long acount=0,failcount=0;vector<E> badA;
int root(int x){while(par[x]!=x)x=par[x];return x;}
bool join(int a,int b){a=root(a);b=root(b);if(a==b)return false;par[a]=b;return true;}
void shortmatch(unsigned m,vector<E>&out){if(!m){out.push_back(cur);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int j=0;j<4;j++){int b=a^(1<<j);if(m>>b&1u){cur.push_back({a,b});shortmatch(m^(1u<<b),out);cur.pop_back();}}}
int spec(const E&f,const E&n,int u,int v,unsigned support){iota(par.begin(),par.end(),0);for(auto[a,b]:f)if(!join(a,b))return -1;for(auto[a,b]:n){for(auto[c,d]:f)if(minmax(a,b)==minmax(c,d))return -1;if(!join(a,b))return -1;}int ends[4]={3,15,u,v};for(int k=1;k<4;k++)if(root(3)==root(ends[k]))return k-1;return -1;}
array<uint64_t,2> sig(const E&f,bool side){array<uint64_t,2> r{};if(!side)r[1]|=1ull<<44;else for(auto&n:twoB){iota(par.begin(),par.end(),0);bool ok=true;for(auto[a,b]:f)if(!join(a,b))ok=false;for(auto[a,b]:n)if(!join(a,b))ok=false;if(ok){r[1]|=1ull<<44;break;}}for(int k=0;k<(int)fam.size();k++){auto&p=fam[k];for(auto&n:side?p.b:p.a){int z=spec(f,n,p.u,p.v,side?65529u:65535u);if(z<0)continue;for(int j=0;j<3;j++)if(!side||j!=z){int bit=3*k+(side?j:z);r[bit/64]|=1ull<<(bit%64);if(!side)break;}}}return r;}
void deggen(array<int,16>d,vector<E>&out){int a=-1;for(int i=0;i<16;i++)if(d[i]){a=i;break;}if(a<0){out.push_back(cur);return;}vector<int>nei;for(int j=0;j<4;j++){int b=a^(1<<j);if(d[b])nei.push_back(b);}int k=d[a];d[a]=0;if(k==1){for(int b:nei){auto e=d;e[b]--;cur.push_back({a,b});deggen(e,out);cur.pop_back();}}else if(k==2){for(int i=0;i<(int)nei.size();i++)for(int j=i+1;j<(int)nei.size();j++){auto e=d;e[nei[i]]--;e[nei[j]]--;cur.push_back({a,nei[i]});cur.push_back({a,nei[j]});deggen(e,out);cur.pop_back();cur.pop_back();}}}
void genB(unsigned m){if(!m){auto z=sig(fb,true);BS.push_back(z);bm[z].push_back(fb);return;}int a=__builtin_ctz(m);m^=1u<<a;for(unsigned t=m;t;t&=t-1){int b=__builtin_ctz(t);fb.push_back({a,b});genB(m^(1u<<b));fb.pop_back();}}
int lift(int x,bool side){return (x&3)|((x&12)<<1)|(side?0:4);}
void genA(unsigned m){if(!m){acount++;auto a=sig(fa,false);bool failed=false;for(auto b:BS)if(!((a[0]&b[0])|(a[1]&b[1]))){failed=true;for(auto&f:bm[b]){++residualcount;for(auto[x,y]:fa){residual.put(char(lift(x,false)));residual.put(char(lift(y,false)));}for(auto[x,y]:f){residual.put(char(lift(x,true)));residual.put(char(lift(y,true)));}}}if(failed){failcount++;if(badA.size()<20)badA.push_back(fa);}return;}int a=__builtin_ctz(m);m^=1u<<a;for(unsigned t=m;t;t&=t-1){int b=__builtin_ctz(t);fa.push_back({a,b});genA(m^(1u<<b));fa.pop_back();}}
int main(){residual.open("research/six_directions/t15_core4_fourbridge_c0_residual_inputs.bin",ios::binary);unsigned coverB=65535u&~((1u<<0)|(1u<<1)|(1u<<2)|(1u<<7));for(int u=0;u<16;u++)for(int v=u+1;v<16;v++){if(u==1||u==2||v==1||v==2||u==3||v==3||u==15||v==15||(__builtin_popcount(unsigned(u^v))%2)!=1)continue;Pat p;p.u=u;p.v=v;cur.clear();shortmatch(65535u&~(1u<<u)&~(1u<<v),p.a);array<int,16>d{};for(int z=0;z<16;z++)if(z!=1&&z!=2)d[z]=(z==0||z==7)?2:1;for(int z:{3,15,u,v})--d[z];cur.clear();deggen(d,p.b);cerr<<u<<","<<v<<" A"<<p.a.size()<<" B"<<p.b.size()<<"\n";fam.push_back(p);}array<int,16>dd{};for(int z=0;z<16;z++)if(z!=1&&z!=2)dd[z]=(z==0||z==7)?2:1;--dd[3];--dd[15];cur.clear();deggen(dd,twoB);cerr<<"twoB "<<twoB.size()<<"\n";cerr<<"families "<<fam.size()<<"\n";genB(coverB);sort(BS.begin(),BS.end());BS.erase(unique(BS.begin(),BS.end()),BS.end());cerr<<"unique B signatures "<<BS.size()<<"\n";genA(65535u&~(1u<<3)&~(1u<<15));cout<<"{\"residual_pairs\":"<<residualcount<<",\"A_count\":"<<acount<<",\"A_with_failure\":"<<failcount<<",\"B_signature_count\":"<<BS.size()<<",\"bad_A_examples\":[";bool sep=false;for(auto&f:badA){if(sep)cout<<",";sep=true;cout<<"[";for(int k=0;k<(int)f.size();k++){if(k)cout<<",";cout<<"["<<f[k].first<<","<<f[k].second<<"]";}cout<<"]";}cout<<"]}\n";}
